import { day } from './dates'
import type { Attr, Day, Fact, Value } from './types'

/**
 * System time is monotonic: a new fact is recorded at the current clock, never
 * before it. Valid time is unconstrained in both directions. The asymmetry is
 * the semantics, not a simplification — valid time is a claim about the world
 * and may be revised, system time is the record of what we did and may not.
 */
export class MonotonicSystemTimeError extends Error {
  constructor(attempted: Day, latest: Day) {
    super(`cannot record at system time ${attempted}: log already reaches ${latest}`)
    this.name = 'MonotonicSystemTimeError'
  }
}

export function latestSystemTime(log: readonly Fact[]): Day {
  return log.reduce((max, f) => (f.systemTime > max ? f.systemTime : max), 0)
}

let counter = 0
export function nextFactId(): string {
  counter += 1
  return `f${counter}`
}

export function makeFact(
  attr: Attr, value: Value, validFrom: Day, systemTime: Day, id = nextFactId(),
): Fact {
  return { id, attr, value, validFrom, systemTime }
}

/** Append a fact, enforcing the monotonic system clock. */
export function append(log: readonly Fact[], fact: Fact): Fact[] {
  const latest = latestSystemTime(log)
  if (fact.systemTime < latest) throw new MonotonicSystemTimeError(fact.systemTime, latest)
  return [...log, fact]
}

/**
 * The scenario from Chronoscope.md, on a calendar.
 *
 * The fourth fact is the whole demo: recorded 10 June, valid from 1 March — after
 * the 1 April manager change was already written. It is also what breaks the
 * uninvalidated snapshot strategy, because the snapshot taken at 1 April carries
 * salary = 60,000 (only the manager changed that day) and nothing goes back to
 * correct it.
 */
export const SCENARIO: Fact[] = [
  makeFact('salary', 60_000, day(2026, 1, 15), day(2026, 1, 15), 'hire-salary'),
  makeFact('manager', 'Jim', day(2026, 1, 15), day(2026, 1, 15), 'hire-manager'),
  makeFact('manager', 'Rob', day(2026, 4, 1), day(2026, 4, 1), 'reorg'),
  makeFact('salary', 72_000, day(2026, 3, 1), day(2026, 6, 10), 'backdated-raise'),
]

/** Window the interface renders. Both axes share it, so the plane is square. */
export const HORIZON = { start: day(2026, 1, 1), end: day(2026, 9, 1) }

import { ATTRS } from './types'
import type { Attr, Day, EntityState, Fact, Value } from './types'

/**
 * The oracle: deliberately slow, obviously correct, and the only thing any
 * strategy is judged against.
 *
 * Keep what we had recorded by `system`, and what had become true by `valid`.
 * The winner is the greatest validFrom; ties — a correction at an existing
 * valid time — go to the greatest systemTime.
 */
export function referenceQuery(
  log: readonly Fact[], attr: Attr, valid: Day, system: Day,
): Value | undefined {
  let best: Fact | undefined
  for (const f of log) {
    if (f.attr !== attr) continue
    if (f.systemTime > system) continue
    if (f.validFrom > valid) continue
    if (
      best === undefined ||
      f.validFrom > best.validFrom ||
      (f.validFrom === best.validFrom && f.systemTime > best.systemTime)
    ) {
      best = f
    }
  }
  return best?.value
}

export function referenceState(
  log: readonly Fact[], valid: Day, system: Day,
): EntityState {
  const state: EntityState = {}
  for (const attr of ATTRS) {
    const v = referenceQuery(log, attr, valid, system)
    if (v !== undefined) state[attr] = v
  }
  return state
}

import type { Attr, Day, Fact, Value } from '../types'

/** Work done by applying one fact. Observed, not modelled. */
export type OpCounts = {
  /** new records appended */
  written: number
  /** existing records closed or rewritten in place */
  rewritten: number
  /** derived state dropped and rebuilt */
  invalidated: number
}

export const NO_OPS: OpCounts = { written: 0, rewritten: 0, invalidated: 0 }

export function addOps(a: OpCounts, b: OpCounts): OpCounts {
  return {
    written: a.written + b.written,
    rewritten: a.rewritten + b.rewritten,
    invalidated: a.invalidated + b.invalidated,
  }
}

export type Config = {
  /** Grid spacing in days for strategies that snapshot on a schedule. */
  snapshotInterval: number
}

export const DEFAULT_CONFIG: Config = { snapshotInterval: 30 }

export type Applied<S> = { state: S; ops: OpCounts }

/**
 * A representation of bitemporal history.
 *
 * `materialize` is deliberately absent: it is always a fold of `apply` over
 * `empty`, so the batch path and the incremental path cannot drift, and the
 * operation counts shown in the interface are the same ones a real write would
 * have paid.
 */
export interface Strategy<S = unknown> {
  key: string
  name: string
  blurb: string
  /** false for the deliberately incorrect strategy. */
  correct: boolean
  empty(cfg: Config): S
  apply(state: S, fact: Fact, cfg: Config): Applied<S>
  query(state: S, attr: Attr, valid: Day, system: Day): Value | undefined
  /** Records the read had to touch. Observation for the strategy row, not a projection. */
  readCost(state: S, attr: Attr, valid: Day, system: Day): number
  /** Records currently stored, for the duplicated-state comparison. */
  size(state: S): number
}

export function materialize<S>(
  strategy: Strategy<S>, log: readonly Fact[], cfg: Config,
): { state: S; ops: OpCounts } {
  let state = strategy.empty(cfg)
  let ops = NO_OPS
  for (const fact of log) {
    const applied = strategy.apply(state, fact, cfg)
    state = applied.state
    ops = addOps(ops, applied.ops)
  }
  return { state, ops }
}

import type { Attr, Day, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'

export type DeltaState = { facts: Fact[] }

/**
 * Store the facts and nothing else. The cheapest possible write and the most
 * expensive possible read: every query replays the whole log. Corrections are
 * free to record and cost nothing extra to store — the price is paid forever
 * afterwards, on every read.
 */
export const deltas: Strategy<DeltaState> = {
  key: 'deltas',
  name: 'Deltas',
  blurb: 'Append-only log of facts. Reads replay.',
  correct: true,

  empty: () => ({ facts: [] }),

  apply(state: DeltaState, fact: Fact, _cfg: Config): Applied<DeltaState> {
    return {
      state: { facts: [...state.facts, fact] },
      ops: { written: 1, rewritten: 0, invalidated: 0 },
    }
  },

  query(state: DeltaState, attr: Attr, valid: Day, system: Day): Value | undefined {
    let best: Fact | undefined
    for (const f of state.facts) {
      if (f.attr !== attr || f.systemTime > system || f.validFrom > valid) continue
      if (
        best === undefined ||
        f.validFrom > best.validFrom ||
        (f.validFrom === best.validFrom && f.systemTime > best.systemTime)
      ) best = f
    }
    return best?.value
  },

  readCost: (state: DeltaState) => state.facts.length,
  size: (state: DeltaState) => state.facts.length,
}

import { INF } from '../types'
import type { Attr, Day, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'

/**
 * A row is a rectangle on the bitemporal plane: a value that held over a range
 * of valid time, believed over a range of system time. Both ends are exclusive,
 * INF meaning still open.
 */
export type Interval = {
  id: string
  attr: Attr
  value: Value
  validFrom: Day
  validTo: Day
  systemFrom: Day
  systemTo: Day
}

export type IntervalState = { rows: Interval[]; seq: number }

const isOpen = (r: Interval) => r.systemTo === INF

/**
 * Validity intervals — the classic bitemporal table.
 *
 * Reads are a direct lookup: find the rectangle containing the coordinate. The
 * price is on write. A retroactive fact does not append, it *rewrites*: every
 * open row it overlaps is closed in system time and reopened with adjusted
 * valid bounds. Nothing is ever mutated in place, so the system-time axis stays
 * an audit trail, but one fact can touch many rows.
 *
 * The subtlety worth reading: the new fact does not run to infinity. It holds
 * only until the next already-known fact supersedes it, so its valid range is
 * clipped at the nearest greater validFrom. Skipping that clip is the classic
 * way to make a retroactive insert silently swallow every later change.
 */
export const intervals: Strategy<IntervalState> = {
  key: 'intervals',
  name: 'Intervals',
  blurb: 'Bitemporal rectangles. Direct reads, rewriting writes.',
  correct: true,

  empty: () => ({ rows: [], seq: 0 }),

  apply(state: IntervalState, fact: Fact, _cfg: Config): Applied<IntervalState> {
    const { attr, value, validFrom: v, systemTime: t } = fact
    let seq = state.seq
    const id = () => `${fact.id}-${++seq}`

    const open = state.rows.filter((r) => r.attr === attr && isOpen(r))

    // The new fact holds until the next thing we already know about.
    let nextValid = INF
    for (const r of open) {
      if (r.validFrom > v && r.validFrom < nextValid) nextValid = r.validFrom
    }

    const rows: Interval[] = []
    let written = 0
    let rewritten = 0

    for (const r of state.rows) {
      const untouched =
        r.attr !== attr || !isOpen(r) || r.validTo <= v || r.validFrom >= nextValid
      if (untouched) {
        rows.push(r)
        continue
      }

      // Close in system time rather than mutating. A zero-width system range can
      // never be read back, so it is dropped rather than stored as noise.
      if (r.systemFrom < t) {
        rows.push({ ...r, systemTo: t })
        rewritten += 1
      } else {
        rewritten += 1
      }

      // Reopen whatever of this row survives on either side of the new fact.
      if (r.validFrom < v) {
        rows.push({ ...r, id: id(), validTo: v, systemFrom: t, systemTo: INF })
        written += 1
      }
      if (r.validTo > nextValid) {
        rows.push({ ...r, id: id(), validFrom: nextValid, systemFrom: t, systemTo: INF })
        written += 1
      }
    }

    rows.push({
      id: id(), attr, value,
      validFrom: v, validTo: nextValid,
      systemFrom: t, systemTo: INF,
    })
    written += 1

    return { state: { rows, seq }, ops: { written, rewritten, invalidated: 0 } }
  },

  query(state: IntervalState, attr: Attr, valid: Day, system: Day): Value | undefined {
    for (const r of state.rows) {
      if (r.attr !== attr) continue
      if (valid < r.validFrom || valid >= r.validTo) continue
      if (system < r.systemFrom || system >= r.systemTo) continue
      return r.value
    }
    return undefined
  },

  readCost: (state: IntervalState, attr: Attr) =>
    state.rows.filter((r) => r.attr === attr).length,
  size: (state: IntervalState) => state.rows.length,
}

import { describe, expect, it } from 'vitest'
import { criticalPoints, generateLog } from './gen'
import { HORIZON, SCENARIO, append, latestSystemTime, makeFact, MonotonicSystemTimeError } from './log'
import { referenceQuery } from './reference'
import { DEFAULT_CONFIG, materialize } from './strategies/index'
import type { Strategy } from './strategies/index'
import { deltas } from './strategies/deltas'
import { intervals } from './strategies/intervals'
import { ATTRS } from './types'
import type { Fact } from './types'
import { day } from './dates'

const CORRECT: Strategy<never>[] = [deltas, intervals] as unknown as Strategy<never>[]

/**
 * Every strategy must agree with the oracle at every coordinate. Because the
 * surface only breaks at recorded times, sweeping the critical points is
 * exhaustive rather than a sample.
 */
function sweep(strategy: Strategy<never>, log: readonly Fact[]): void {
  const { state } = materialize(strategy, log, DEFAULT_CONFIG)
  const valids = criticalPoints(log.map((f) => f.validFrom), HORIZON.start, HORIZON.end)
  const systems = criticalPoints(log.map((f) => f.systemTime), HORIZON.start, HORIZON.end)

  for (const attr of ATTRS) {
    for (const v of valids) {
      for (const s of systems) {
        const expected = referenceQuery(log, attr, v, s)
        const actual = strategy.query(state, attr, v, s)
        if (actual !== expected) {
          throw new Error(
            `${strategy.name}: ${attr} at valid=${v} system=${s} ` +
            `gave ${String(actual)}, oracle says ${String(expected)}`,
          )
        }
      }
    }
  }
}

describe('the monotonic system clock', () => {
  it('refuses a fact recorded before what the log already knows', () => {
    expect(() => append(SCENARIO, makeFact('salary', 1, 0, day(2026, 2, 1))))
      .toThrow(MonotonicSystemTimeError)
  })

  it('accepts a fact recorded at the current clock', () => {
    const now = latestSystemTime(SCENARIO)
    expect(() => append(SCENARIO, makeFact('salary', 1, 0, now))).not.toThrow()
  })

  it('accepts any valid time, past or future', () => {
    const now = latestSystemTime(SCENARIO)
    expect(() => append(SCENARIO, makeFact('salary', 1, HORIZON.start, now))).not.toThrow()
    expect(() => append(SCENARIO, makeFact('salary', 1, HORIZON.end, now))).not.toThrow()
  })
})

describe('the scenario', () => {
  for (const strategy of CORRECT) {
    it(`${strategy.name} agrees with the oracle everywhere`, () => {
      sweep(strategy, SCENARIO)
    })
  }

  it('the backdated raise is invisible until it is recorded', () => {
    const may = day(2026, 5, 1)
    expect(referenceQuery(SCENARIO, 'salary', may, day(2026, 6, 1))).toBe(60_000)
    expect(referenceQuery(SCENARIO, 'salary', may, day(2026, 6, 10))).toBe(72_000)
  })

  it('and it rewrites March onward, not just the present', () => {
    const now = day(2026, 6, 10)
    expect(referenceQuery(SCENARIO, 'salary', day(2026, 2, 28), now)).toBe(60_000)
    expect(referenceQuery(SCENARIO, 'salary', day(2026, 3, 1), now)).toBe(72_000)
  })
})

describe('generated histories', () => {
  for (let seed = 0; seed < 40; seed++) {
    const log = generateLog(seed, 14)
    for (const strategy of CORRECT) {
      it(`${strategy.name} agrees with the oracle, seed ${seed}`, () => {
        sweep(strategy, log)
      })
    }
  }
})

describe('a retroactive insert', () => {
  it('does not swallow later changes it was recorded after', () => {
    // salary 10 from Jan, 15 from May, then 20 backdated to March. March's raise
    // must stop at May, not run over it.
    const log: Fact[] = [
      makeFact('salary', 10, day(2026, 1, 1), day(2026, 1, 1), 'a'),
      makeFact('salary', 15, day(2026, 5, 1), day(2026, 5, 1), 'b'),
      makeFact('salary', 20, day(2026, 3, 1), day(2026, 6, 1), 'c'),
    ]
    const now = day(2026, 6, 1)
    expect(referenceQuery(log, 'salary', day(2026, 4, 1), now)).toBe(20)
    expect(referenceQuery(log, 'salary', day(2026, 6, 1), now)).toBe(15)
    for (const strategy of CORRECT) sweep(strategy, log)
  })

  it('is superseded by a correction at the same valid time', () => {
    const log: Fact[] = [
      makeFact('salary', 10, day(2026, 1, 1), day(2026, 1, 1), 'a'),
      makeFact('salary', 20, day(2026, 3, 1), day(2026, 6, 1), 'b'),
      makeFact('salary', 25, day(2026, 3, 1), day(2026, 7, 1), 'c'),
    ]
    expect(referenceQuery(log, 'salary', day(2026, 4, 1), day(2026, 6, 15))).toBe(20)
    expect(referenceQuery(log, 'salary', day(2026, 4, 1), day(2026, 7, 1))).toBe(25)
    for (const strategy of CORRECT) sweep(strategy, log)
  })
})

import { HORIZON, makeFact } from './log'
import { ATTRS } from './types'
import type { Day, Fact } from './types'

/** Seeded, so a failing fuzz case is reproducible from its seed alone. */
export function rng(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const MANAGERS = ['Jim', 'Rob', 'Dana', 'Erin', 'Sam']

/**
 * A random but legal history: valid times scattered freely across the horizon,
 * system time advancing monotonically. Deliberately generates same-day
 * recordings, corrections at an existing valid time, retroactive inserts and
 * facts valid in the future — the cases a fixed scenario cannot cover.
 */
export function generateLog(seed: number, count: number): Fact[] {
  const r = rng(seed)
  const span = HORIZON.end - HORIZON.start
  const pick = <T,>(xs: readonly T[]): T => xs[Math.floor(r() * xs.length)]!

  let clock: Day = HORIZON.start
  const log: Fact[] = []
  for (let i = 0; i < count; i++) {
    clock += Math.floor(r() * 21) // 0 allows several recordings on one day
    const attr = pick(ATTRS)
    const value = attr === 'salary'
      ? 40_000 + Math.floor(r() * 12) * 5_000
      : pick(MANAGERS)
    const validFrom = HORIZON.start + Math.floor(r() * span)
    log.push(makeFact(attr, value, validFrom, clock, `g${seed}-${i}`))
  }
  return log
}

/**
 * The value surface is piecewise constant, breaking only at recorded
 * coordinates. Sweeping these points and their immediate neighbours is
 * therefore exhaustive, not a sample — every distinct region is visited.
 */
export function criticalPoints(values: readonly Day[], lo: Day, hi: Day): Day[] {
  const set = new Set<Day>([lo, hi])
  for (const v of values) {
    for (const d of [v - 1, v, v + 1]) {
      if (d >= lo && d <= hi) set.add(d)
    }
  }
  return [...set].sort((a, b) => a - b)
}

